export function CodexPanelIcon({ name, size = 18 }) {
  const icon = CODEX_PANEL_ICONS[name]
  if (!icon) throw new Error(`unknown Codex panel icon: ${name}`)
  const paths = icon.paths.map((path) => createElement('path', {
    key: path,
    d: path,
    fill: 'currentColor',
  }))
  const body = icon.transform
    ? createElement('g', { transform: icon.transform }, paths)
    : paths
  return createElement('svg', {
    width: size,
    height: size,
    viewBox: icon.viewBox,
    fill: 'none',
    'aria-hidden': true,
  }, body)
}
